files.app/main.pseudo:
Importar app.worker.Work;
Algoritmo Main
Definir Mutable number Como Entero <- 0;
Leer number;
Tareas
Lanzar Work(number);
Lanzar Work(number + 1);
FinTareas
FinAlgoritmo

files.app/worker.pseudo:
Importar app.math.Double;
Publico SubProceso Suspendible Work(number Como Entero)
Escribir Double(number);
FinSubProceso

files.app/math.pseudo:
Publico SubProceso Double(number Como Entero) Como Entero
Retornar number * 2;
FinSubProceso
